def bisection(f, a, b, tol=1e-5, max_iter=100):
    if f(a) * f(b) >= 0:
        raise ValueError("f(a) and f(b) must have opposite signs.")

    for _ in range(max_iter):
        c = (a + b) / 2
        if abs(b - a) < tol or f(c) == 0:
            return c
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c
    return (a + b) / 2

# Example usage:
# root = bisection(lambda x: x**2 - 4, 1, 3)
# print(f"Root found: {root}")
